/** static int DoSameJumpTimeBonus(u8 flags) */
export function DoSameJumpTimeBonus(flags: any): any {
  let i, numPlayers;

      for (i = 0, numPlayers = 0; i < MAX_RFU_PLAYERS; i++)
      {
          if (flags & 1)
          {
               
               
              DoStarAnim(sPokemonJumpGfx, i);
              numPlayers++;
          }
          flags >>= 1;
      }

      ShowBonus(numPlayers - 2);
      return numPlayers;
}

